insert into public.lessons(id,course_id,slug,title,subject,position,body) select 'd6100000-0000-4000-8000-000000000001','d6010000-0000-4000-8000-000000000002','workplace-conversation','Offer assistance','grammar',0,'{"text":"A resident is seated. Ask permission before offering help.","examples":[{"japanese":"何かお{手伝|てつだ}いしましょうか。","english":"May I help you with anything?"},{"japanese":"はい、お願いします。","english":"Yes, please."}],"explanationEn":"Ask rather than assume. This respects the person’s choice; it is language practice, not clinical instruction.","explanationJa":"相手の希望を確認し、丁寧に申し出ます。専門的な介助手順の練習ではありません。"}' where not exists(select 1 from public.lessons where id='d6100000-0000-4000-8000-000000000001') on conflict do nothing;
insert into public.workplace_scenarios(id,sector_id,lesson_id,bank_id,title,situation,situation_ja,dialogue) select 'd6090000-0000-4000-8000-000000000001','d6030000-0000-4000-8000-000000000001','d6100000-0000-4000-8000-000000000001','d6020000-0000-4000-8000-000000000015','Offer assistance','A resident is seated. Ask permission before offering help.','利用者の方に、手伝いが必要か丁寧に尋ねます。','[{"speaker":"職員","ja":"何かお{手伝|てつだ}いしましょうか。","en":"May I help you with anything?"},{"speaker":"利用者","ja":"はい、お願いします。","en":"Yes, please."}]' where not exists(select 1 from public.workplace_scenarios where id='d6090000-0000-4000-8000-000000000001') on conflict do nothing;
insert into public.lessons(id,course_id,slug,title,subject,position,body) select 'd6100000-0000-4000-8000-000000000002','d6010000-0000-4000-8000-000000000003','workplace-conversation','Confirm an order','grammar',0,'{"text":"A guest orders tea. Confirm the order politely.","examples":[{"japanese":"お{茶|ちゃ}を一つお願いします。","english":"One tea, please."},{"japanese":"お{茶|ちゃ}をお一つですね。","english":"One tea, correct?"}],"explanationEn":"Repeating the item and quantity politely checks the order.","explanationJa":"品物と数を繰り返して、注文を確認します。"}' where not exists(select 1 from public.lessons where id='d6100000-0000-4000-8000-000000000002') on conflict do nothing;
insert into public.workplace_scenarios(id,sector_id,lesson_id,bank_id,title,situation,situation_ja,dialogue) select 'd6090000-0000-4000-8000-000000000002','d6030000-0000-4000-8000-000000000002','d6100000-0000-4000-8000-000000000002','d6020000-0000-4000-8000-000000000016','Confirm an order','A guest orders tea. Confirm the order politely.','お客様がお茶を注文しました。内容を確認します。','[{"speaker":"お客様","ja":"お{茶|ちゃ}を一つお願いします。","en":"One tea, please."},{"speaker":"店員","ja":"お{茶|ちゃ}をお一つですね。","en":"One tea, correct?"}]' where not exists(select 1 from public.workplace_scenarios where id='d6090000-0000-4000-8000-000000000002') on conflict do nothing;
insert into public.lessons(id,course_id,slug,title,subject,position,body) select 'd6100000-0000-4000-8000-000000000003','d6010000-0000-4000-8000-000000000004','workplace-conversation','Welcome a guest','grammar',0,'{"text":"A guest arrives at the hotel. Ask for the reservation name.","examples":[{"japanese":"いらっしゃいませ。ご{予約|よやく}はございますか。","english":"Welcome. Do you have a reservation?"},{"japanese":"はい、田中です。","english":"Yes, under Tanaka."}],"explanationEn":"伺ってもよろしいですか politely requests information from a guest.","explanationJa":"「伺ってもよろしいですか」で丁寧に尋ねます。"}' where not exists(select 1 from public.lessons where id='d6100000-0000-4000-8000-000000000003') on conflict do nothing;
insert into public.workplace_scenarios(id,sector_id,lesson_id,bank_id,title,situation,situation_ja,dialogue) select 'd6090000-0000-4000-8000-000000000003','d6030000-0000-4000-8000-000000000003','d6100000-0000-4000-8000-000000000003','d6020000-0000-4000-8000-000000000017','Welcome a guest','A guest arrives at the hotel. Ask for the reservation name.','ホテルに到着したお客様に、予約のお名前を伺います。','[{"speaker":"スタッフ","ja":"いらっしゃいませ。ご{予約|よやく}はございますか。","en":"Welcome. Do you have a reservation?"},{"speaker":"お客様","ja":"はい、田中です。","en":"Yes, under Tanaka."}]' where not exists(select 1 from public.workplace_scenarios where id='d6090000-0000-4000-8000-000000000003') on conflict do nothing;
insert into public.lessons(id,course_id,slug,title,subject,position,body) select 'd6100000-0000-4000-8000-000000000004','d6010000-0000-4000-8000-000000000005','workplace-conversation','Clarify a safety instruction','grammar',0,'{"text":"You do not understand a supervisor’s instruction. Ask for clarification before proceeding.","examples":[{"japanese":"ここから先は{立入禁止|たちいりきんし}です。","english":"Do not enter beyond this point."},{"japanese":"分かりました。{範囲|はんい}をもう一度{教|おし}えてください。","english":"Understood. Please show me the boundary again."}],"explanationEn":"Ask for clarification rather than acting on an unclear instruction. Follow trained supervision and workplace procedures.","explanationJa":"分からない指示は確認します。実際の安全判断や作業は職場の訓練と手順に従います。"}' where not exists(select 1 from public.lessons where id='d6100000-0000-4000-8000-000000000004') on conflict do nothing;
insert into public.workplace_scenarios(id,sector_id,lesson_id,bank_id,title,situation,situation_ja,dialogue) select 'd6090000-0000-4000-8000-000000000004','d6030000-0000-4000-8000-000000000004','d6100000-0000-4000-8000-000000000004','d6020000-0000-4000-8000-000000000018','Clarify a safety instruction','You do not understand a supervisor’s instruction. Ask for clarification before proceeding.','上司の安全に関する指示が分かりません。作業前に確認します。','[{"speaker":"上司","ja":"ここから先は{立入禁止|たちいりきんし}です。","en":"Do not enter beyond this point."},{"speaker":"作業員","ja":"分かりました。{範囲|はんい}をもう一度{教|おし}えてください。","en":"Understood. Please show me the boundary again."}]' where not exists(select 1 from public.workplace_scenarios where id='d6090000-0000-4000-8000-000000000004') on conflict do nothing;
insert into public.lessons(id,course_id,slug,title,subject,position,body) select 'd6100000-0000-4000-8000-000000000005','d6010000-0000-4000-8000-000000000006','workplace-conversation','Report a machine problem','grammar',0,'{"text":"You notice an unusual sound. Report what you noticed to the supervisor.","examples":[{"japanese":"{機械|きかい}からいつもと違う音がします。","english":"The machine is making an unusual sound."},{"japanese":"分かりました。{担当者|たんとうしゃ}に{確認|かくにん}します。","english":"Understood. I will check with the person responsible."}],"explanationEn":"Describe the observed problem clearly; this exercise does not teach machine operation or emergency response.","explanationJa":"気づいたことを具体的に報告します。機械の操作方法を教える問題ではありません。"}' where not exists(select 1 from public.lessons where id='d6100000-0000-4000-8000-000000000005') on conflict do nothing;
insert into public.workplace_scenarios(id,sector_id,lesson_id,bank_id,title,situation,situation_ja,dialogue) select 'd6090000-0000-4000-8000-000000000005','d6030000-0000-4000-8000-000000000005','d6100000-0000-4000-8000-000000000005','d6020000-0000-4000-8000-000000000019','Report a machine problem','You notice an unusual sound. Report what you noticed to the supervisor.','機械の音がいつもと違います。気づいたことを上司に報告します。','[{"speaker":"作業員","ja":"{機械|きかい}からいつもと違う音がします。","en":"The machine is making an unusual sound."},{"speaker":"上司","ja":"分かりました。{担当者|たんとうしゃ}に{確認|かくにん}します。","en":"Understood. I will check with the person responsible."}]' where not exists(select 1 from public.workplace_scenarios where id='d6090000-0000-4000-8000-000000000005') on conflict do nothing;
insert into public.lessons(id,course_id,slug,title,subject,position,body) select 'd6100000-0000-4000-8000-000000000006','d6010000-0000-4000-8000-000000000007','workplace-conversation','Confirm a field task','grammar',0,'{"text":"Your supervisor asks you to sort produce. Ask which standard to use.","examples":[{"japanese":"この箱の{野菜|やさい}を{選別|せんべつ}してください。","english":"Please sort the vegetables in this box."},{"japanese":"{選別|せんべつ}の{基準|きじゅん}を{教|おし}えてください。","english":"Please explain the sorting criteria."}],"explanationEn":"Ask for the criteria before starting an unfamiliar task.","explanationJa":"初めての作業では、基準を確認してから始めます。"}' where not exists(select 1 from public.lessons where id='d6100000-0000-4000-8000-000000000006') on conflict do nothing;
insert into public.workplace_scenarios(id,sector_id,lesson_id,bank_id,title,situation,situation_ja,dialogue) select 'd6090000-0000-4000-8000-000000000006','d6030000-0000-4000-8000-000000000006','d6100000-0000-4000-8000-000000000006','d6020000-0000-4000-8000-000000000020','Confirm a field task','Your supervisor asks you to sort produce. Ask which standard to use.','農産物の選別を頼まれました。基準を確認します。','[{"speaker":"上司","ja":"この箱の{野菜|やさい}を{選別|せんべつ}してください。","en":"Please sort the vegetables in this box."},{"speaker":"作業員","ja":"{選別|せんべつ}の{基準|きじゅん}を{教|おし}えてください。","en":"Please explain the sorting criteria."}]' where not exists(select 1 from public.workplace_scenarios where id='d6090000-0000-4000-8000-000000000006') on conflict do nothing;
insert into public.lessons(id,course_id,slug,title,subject,position,body) select 'd6100000-0000-4000-8000-000000000007','d6010000-0000-4000-8000-000000000008','interview-1','Introduction interview practice','grammar',0,'{"text":"自己紹介をお願いします。","examples":[{"japanese":"はじめまして。〇〇と申します。{日本語|にほんご}を勉強しています。本日はよろしくお願いいたします。","english":"My name is __. I am studying Japanese. Thank you for meeting with me today."},{"japanese":"本日はお時間をいただき、ありがとうございます。","english":"Thank you for taking the time to meet with me today."}],"explanationEn":"Replace 〇〇 with your name. Keep your introduction brief and truthful.","explanationJa":"〇〇を自分の名前に変えて、簡潔に伝えます。"}' where not exists(select 1 from public.lessons where id='d6100000-0000-4000-8000-000000000007') on conflict do nothing;
insert into public.interview_questions(id,sector_id,lesson_id,topic,prompt,suggested_answer,translation,explanation,explanation_ja) select 'd6110000-0000-4000-8000-000000000001',null,'d6100000-0000-4000-8000-000000000007','Introduction','自己紹介をお願いします。','はじめまして。〇〇と申します。{日本語|にほんご}を勉強しています。本日はよろしくお願いいたします。','My name is __. I am studying Japanese. Thank you for meeting with me today.','Replace 〇〇 with your name. Keep your introduction brief and truthful.','〇〇を自分の名前に変えて、簡潔に伝えます。' where not exists(select 1 from public.interview_questions where id='d6110000-0000-4000-8000-000000000001') on conflict do nothing;
insert into public.lessons(id,course_id,slug,title,subject,position,body) select 'd6100000-0000-4000-8000-000000000008','d6010000-0000-4000-8000-000000000008','interview-2','Work experience interview practice','grammar',1,'{"text":"これまでの{仕事|しごと}について{教|おし}えてください。","examples":[{"japanese":"以前は〇〇の{仕事|しごと}をしていました。主に〇〇を担当していました。","english":"Previously I worked in __. My main responsibility was __."},{"japanese":"本日はお時間をいただき、ありがとうございます。","english":"Thank you for taking the time to meet with me today."}],"explanationEn":"Describe only your actual experience. If you have none, explain what you have learned instead.","explanationJa":"実際の経験を伝えます。未経験なら、学んだことを説明します。"}' where not exists(select 1 from public.lessons where id='d6100000-0000-4000-8000-000000000008') on conflict do nothing;
insert into public.interview_questions(id,sector_id,lesson_id,topic,prompt,suggested_answer,translation,explanation,explanation_ja) select 'd6110000-0000-4000-8000-000000000002',null,'d6100000-0000-4000-8000-000000000008','Work experience','これまでの{仕事|しごと}について{教|おし}えてください。','以前は〇〇の{仕事|しごと}をしていました。主に〇〇を担当していました。','Previously I worked in __. My main responsibility was __.','Describe only your actual experience. If you have none, explain what you have learned instead.','実際の経験を伝えます。未経験なら、学んだことを説明します。' where not exists(select 1 from public.interview_questions where id='d6110000-0000-4000-8000-000000000002') on conflict do nothing;
insert into public.lessons(id,course_id,slug,title,subject,position,body) select 'd6100000-0000-4000-8000-000000000009','d6010000-0000-4000-8000-000000000008','interview-3','Motivation interview practice','grammar',2,'{"text":"なぜ日本で働きたいですか。","examples":[{"japanese":"{日本語|にほんご}を使って働き、〇〇の技術を学びたいと考えています。","english":"I would like to work using Japanese and learn skills in __."},{"japanese":"本日はお時間をいただき、ありがとうございます。","english":"Thank you for taking the time to meet with me today."}],"explanationEn":"Give your own specific motivation; do not present this template as a personal fact.","explanationJa":"自分の具体的な理由に合わせて答えます。"}' where not exists(select 1 from public.lessons where id='d6100000-0000-4000-8000-000000000009') on conflict do nothing;
insert into public.interview_questions(id,sector_id,lesson_id,topic,prompt,suggested_answer,translation,explanation,explanation_ja) select 'd6110000-0000-4000-8000-000000000003',null,'d6100000-0000-4000-8000-000000000009','Motivation','なぜ日本で働きたいですか。','{日本語|にほんご}を使って働き、〇〇の技術を学びたいと考えています。','I would like to work using Japanese and learn skills in __.','Give your own specific motivation; do not present this template as a personal fact.','自分の具体的な理由に合わせて答えます。' where not exists(select 1 from public.interview_questions where id='d6110000-0000-4000-8000-000000000003') on conflict do nothing;
insert into public.lessons(id,course_id,slug,title,subject,position,body) select 'd6100000-0000-4000-8000-000000000010','d6010000-0000-4000-8000-000000000008','interview-4','Strengths interview practice','grammar',3,'{"text":"あなたの長所を{教|おし}えてください。","examples":[{"japanese":"私の長所は、分からないことを{確認|かくにん}してから行動することです。","english":"My strength is checking what I do not understand before acting."},{"japanese":"本日はお時間をいただき、ありがとうございます。","english":"Thank you for taking the time to meet with me today."}],"explanationEn":"Support a truthful strength with an example from your own life.","explanationJa":"本当の長所を、自分の経験を添えて説明します。"}' where not exists(select 1 from public.lessons where id='d6100000-0000-4000-8000-000000000010') on conflict do nothing;
insert into public.interview_questions(id,sector_id,lesson_id,topic,prompt,suggested_answer,translation,explanation,explanation_ja) select 'd6110000-0000-4000-8000-000000000004',null,'d6100000-0000-4000-8000-000000000010','Strengths','あなたの長所を{教|おし}えてください。','私の長所は、分からないことを{確認|かくにん}してから行動することです。','My strength is checking what I do not understand before acting.','Support a truthful strength with an example from your own life.','本当の長所を、自分の経験を添えて説明します。' where not exists(select 1 from public.interview_questions where id='d6110000-0000-4000-8000-000000000004') on conflict do nothing;
insert into public.lessons(id,course_id,slug,title,subject,position,body) select 'd6100000-0000-4000-8000-000000000011','d6010000-0000-4000-8000-000000000008','interview-5','Areas to improve interview practice','grammar',4,'{"text":"{改善|かいぜん}したい点はありますか。","examples":[{"japanese":"{日本語|にほんご}で話すとき、まだ時間がかかります。毎日声に出して練習しています。","english":"Speaking Japanese still takes me time. I practise speaking aloud every day."},{"japanese":"本日はお時間をいただき、ありがとうございます。","english":"Thank you for taking the time to meet with me today."}],"explanationEn":"State a real area for improvement and the steps you are taking.","explanationJa":"改善したい点と、そのための努力を伝えます。"}' where not exists(select 1 from public.lessons where id='d6100000-0000-4000-8000-000000000011') on conflict do nothing;
insert into public.interview_questions(id,sector_id,lesson_id,topic,prompt,suggested_answer,translation,explanation,explanation_ja) select 'd6110000-0000-4000-8000-000000000005',null,'d6100000-0000-4000-8000-000000000011','Areas to improve','{改善|かいぜん}したい点はありますか。','{日本語|にほんご}で話すとき、まだ時間がかかります。毎日声に出して練習しています。','Speaking Japanese still takes me time. I practise speaking aloud every day.','State a real area for improvement and the steps you are taking.','改善したい点と、そのための努力を伝えます。' where not exists(select 1 from public.interview_questions where id='d6110000-0000-4000-8000-000000000005') on conflict do nothing;
insert into public.lessons(id,course_id,slug,title,subject,position,body) select 'd6100000-0000-4000-8000-000000000012','d6010000-0000-4000-8000-000000000008','interview-6','Polite clarification interview practice','grammar',5,'{"text":"{質問|しつもん}が聞き取れないとき、どう言いますか。","examples":[{"japanese":"申し訳ありません。もう一度、ゆっくりお話しいただけますか。","english":"I am sorry. Could you please say that again slowly?"},{"japanese":"本日はお時間をいただき、ありがとうございます。","english":"Thank you for taking the time to meet with me today."}],"explanationEn":"It is appropriate to request clarification instead of pretending to understand.","explanationJa":"分かったふりをせず、丁寧に聞き直します。"}' where not exists(select 1 from public.lessons where id='d6100000-0000-4000-8000-000000000012') on conflict do nothing;
insert into public.interview_questions(id,sector_id,lesson_id,topic,prompt,suggested_answer,translation,explanation,explanation_ja) select 'd6110000-0000-4000-8000-000000000006',null,'d6100000-0000-4000-8000-000000000012','Polite clarification','{質問|しつもん}が聞き取れないとき、どう言いますか。','申し訳ありません。もう一度、ゆっくりお話しいただけますか。','I am sorry. Could you please say that again slowly?','It is appropriate to request clarification instead of pretending to understand.','分かったふりをせず、丁寧に聞き直します。' where not exists(select 1 from public.interview_questions where id='d6110000-0000-4000-8000-000000000006') on conflict do nothing;
insert into public.lessons(id,course_id,slug,title,subject,position,body) select 'd6100000-0000-4000-8000-000000000013','d6010000-0000-4000-8000-000000000008','interview-7','Closing questions interview practice','grammar',6,'{"text":"最後に{質問|しつもん}はありますか。","examples":[{"japanese":"入社後の{研修|けんしゅう}について{教|おし}えていただけますか。","english":"Could you tell me about the training after joining?"},{"japanese":"本日はお時間をいただき、ありがとうございます。","english":"Thank you for taking the time to meet with me today."}],"explanationEn":"Ask a genuine question about the role or training.","explanationJa":"仕事内容や研修について、知りたいことを丁寧に尋ねます。"}' where not exists(select 1 from public.lessons where id='d6100000-0000-4000-8000-000000000013') on conflict do nothing;
insert into public.interview_questions(id,sector_id,lesson_id,topic,prompt,suggested_answer,translation,explanation,explanation_ja) select 'd6110000-0000-4000-8000-000000000007',null,'d6100000-0000-4000-8000-000000000013','Closing questions','最後に{質問|しつもん}はありますか。','入社後の{研修|けんしゅう}について{教|おし}えていただけますか。','Could you tell me about the training after joining?','Ask a genuine question about the role or training.','仕事内容や研修について、知りたいことを丁寧に尋ねます。' where not exists(select 1 from public.interview_questions where id='d6110000-0000-4000-8000-000000000007') on conflict do nothing;
insert into public.lessons(id,course_id,slug,title,subject,position,body) select 'd6100000-0000-4000-8000-000000000014','d6010000-0000-4000-8000-000000000002','interview-8','Nursing care interview practice','grammar',1,'{"text":"この{仕事|しごと}で大切だと思うことは何ですか。","examples":[{"japanese":"分からないことを{確認|かくにん}し、周りの人と丁寧に話すことが大切だと考えています。","english":"I think it is important to check what I do not understand and communicate respectfully with others."},{"japanese":"本日はお時間をいただき、ありがとうございます。","english":"Thank you for taking the time to meet with me today."}],"explanationEn":"For nursing care, connect this answer to a truthful experience. Language practice alone does not demonstrate professional competence.","explanationJa":"自分の経験に合わせて答えます。日本語の練習だけで専門的な能力を証明するものではありません。"}' where not exists(select 1 from public.lessons where id='d6100000-0000-4000-8000-000000000014') on conflict do nothing;
insert into public.interview_questions(id,sector_id,lesson_id,topic,prompt,suggested_answer,translation,explanation,explanation_ja) select 'd6110000-0000-4000-8000-000000000008','d6030000-0000-4000-8000-000000000001','d6100000-0000-4000-8000-000000000014','Nursing care','この{仕事|しごと}で大切だと思うことは何ですか。','分からないことを{確認|かくにん}し、周りの人と丁寧に話すことが大切だと考えています。','I think it is important to check what I do not understand and communicate respectfully with others.','For nursing care, connect this answer to a truthful experience. Language practice alone does not demonstrate professional competence.','自分の経験に合わせて答えます。日本語の練習だけで専門的な能力を証明するものではありません。' where not exists(select 1 from public.interview_questions where id='d6110000-0000-4000-8000-000000000008') on conflict do nothing;
