insert into public.official_resources(id,sector_id,category,title,url,summary,summary_ja,reviewed_at) select 'd6120000-0000-4000-8000-000000000001',null,'jft','Japan Foundation · JFT-Basic structure','https://www.jpf.go.jp/jft-basic/e/about/index.html','Four sections, around 50 questions in 60 minutes. Review stays within the current section; listening does not allow previous/next review.','四分野、約50問、60分です。前の分野には戻れず、聴解では前後の問題を見直せません。','2026-10-24' where not exists(select 1 from public.official_resources where id='d6120000-0000-4000-8000-000000000001') on conflict do nothing;
insert into public.official_resources(id,sector_id,category,title,url,summary,summary_ja,reviewed_at) select 'd6120000-0000-4000-8000-000000000002',null,'ssw','Immigration Services Agency · SSW fields','https://www.ssw.go.jp/en/about/visa/','Consult the current official sector pages. The six NihonPath tracks are a learning subset, not a complete eligibility list. The food-service page currently notes a pause on new applications.','最新の分野情報は公式ページで確認してください。当サイトの六つの学習分野は全対象分野の一覧ではありません。外食分野には新規申請に関する停止の案内があります。','2026-10-24' where not exists(select 1 from public.official_resources where id='d6120000-0000-4000-8000-000000000002') on conflict do nothing;
insert into public.official_resources(id,sector_id,category,title,url,summary,summary_ja,reviewed_at) select 'd6120000-0000-4000-8000-000000000003',null,'ssw','Prometric · Tests and schedules','https://www.prometric-jp.com/ssw/','Check the test provider for current examination subjects, locations and booking dates. NihonPath does not make test reservations.','試験科目、会場、予約日程は試験実施機関で確認してください。当サイトでは試験の予約を行いません。','2026-10-24' where not exists(select 1 from public.official_resources where id='d6120000-0000-4000-8000-000000000003') on conflict do nothing;
insert into public.official_resources(id,sector_id,category,title,url,summary,summary_ja,reviewed_at) select 'd6120000-0000-4000-8000-000000000004','d6030000-0000-4000-8000-000000000001','ssw','ISA · Nursing care language requirements','https://www.ssw.go.jp/en/about/visa/nursing_care_1/','The nursing care field lists JLPT N4 or higher or JFT-Basic, plus its additional nursing care Japanese evaluation. Skill tests and any exemptions must be checked on the official pages.','介護分野にはJLPT N4以上またはJFT-Basicに加え、介護日本語評価試験の案内があります。技能試験や免除条件は公式情報で確認してください。','2026-10-24' where not exists(select 1 from public.official_resources where id='d6120000-0000-4000-8000-000000000004') on conflict do nothing;
insert into public.official_resources(id,sector_id,category,title,url,summary,summary_ja,reviewed_at) select 'd6120000-0000-4000-8000-000000000005','d6030000-0000-4000-8000-000000000002','ssw','ISA · Food service skills & language guidance','https://www.ssw.go.jp/en/about/visa/food_service_1/','The official notice describes a suspension of certificate-of-eligibility issuance and links to skills-test booking restrictions. Check current updates before planning.','公式ページには在留資格認定証明書の交付停止や技能試験の予約制限に関する案内があります。計画前に最新情報を確認してください。','2026-10-24' where not exists(select 1 from public.official_resources where id='d6120000-0000-4000-8000-000000000005') on conflict do nothing;
insert into public.official_resources(id,sector_id,category,title,url,summary,summary_ja,reviewed_at) select 'd6120000-0000-4000-8000-000000000006','d6030000-0000-4000-8000-000000000003','ssw','ISA · Accommodation skills & language guidance','https://www.ssw.go.jp/en/about/visa/accommodation_1/','Read the official field-specific skills assessment, Japanese language standards and exemption guidance. This learning track does not replace the skills assessment.','分野別の技能評価、日本語要件、免除条件は公式ページで確認してください。この学習教材は技能評価試験の代わりではありません。','2026-10-24' where not exists(select 1 from public.official_resources where id='d6120000-0000-4000-8000-000000000006') on conflict do nothing;
